(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(3200);
  out.work = document.querySelector('.pj-title')?.textContent || null;

  let captured = null;
  const orig = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { captured = b; return orig(b); };

  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('分享作品'))?.click();
  await sleep(1600);
  out.modalOpen = !!document.querySelector('.sw-modal');

  // ① 生成分享页
  [...document.querySelectorAll('.sw-btn')].find((b) => b.textContent.includes('生成分享页'))?.click();
  await sleep(4000);
  out.sharePageMsg = document.querySelector('.sw-msg')?.textContent || null;
  out.gotHtml = !!captured;
  out.htmlBytes = captured?.size || null;
  const html = captured ? await captured.text() : '';
  out.embedsWorkFile = /data:application\/zip;base64,[A-Za-z0-9+/=]{500,}/.test(html);
  out.leaksCredential = /sk-[A-Za-z0-9]{6,}|api[_-]?key|ai_config|teacherCode|proxyToken/i.test(html);
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const text = (doc.body?.textContent || '').replace(/\s+/g, ' ').trim();
  const banned = ['API Key', 'API key', 'apikey', '密钥', 'JSON', 'json', '导入', '导出', '项目包', 'token', '令牌'];
  out.studentBannedHits = banned.filter((b) => text.includes(b));
  out.studentText = text.slice(0, 200);

  // ② 作品码
  captured = null;
  [...document.querySelectorAll('.sw-btn')].find((b) => b.textContent.includes('生成作品码'))?.click();
  await sleep(3000);
  const code = document.querySelector('.sw-code textarea')?.value || '';
  out.workCodeLen = code.length;
  out.workCodePrefix = code.slice(0, 5);
  out.codeNote = document.querySelector('.sw-note')?.textContent || null;

  // ③ 作品文件
  captured = null;
  [...document.querySelectorAll('.sw-btn')].find((b) => b.textContent.includes('保存作品文件'))?.click();
  await sleep(3000);
  out.fileBytes = captured?.size || null;
  out.fileMsg = document.querySelector('.sw-msg')?.textContent || null;
  URL.createObjectURL = orig;
  return JSON.stringify(out);
})()
